+function installKitFieldMethods<E extends KitPathEntity>(
+  ctor: abstract new (...args: never[]) => E,
+  specs: readonly BoundKitFieldSpec<unknown>[],
+): void {
+  for (const spec of specs) {
+    Object.defineProperty(ctor.prototype, spec.methodName, {
+      configurable: true,
+      value: function semioKitField(this: E): Promise<unknown> {
+        return defineField(this, spec, (self) => self.kitInnerPath(spec.selection))();
